using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 sealed class WorkshopPlan {public readonly Dictionary<ulong,string> Paths=new Dictionary<ulong,string>();public readonly List<ulong> Needed=new List<ulong>();}
 static class WorkshopUpdate {
  static Dictionary<string,object> Parse(string text){var tokens=Regex.Matches(text,"\"(?:\\\\.|[^\"\\\\])*\"|[{}]").Cast<Match>().Select(m=>m.Value).ToArray();int index=0;return Read(tokens,ref index);}
  static Dictionary<string,object> Read(string[] tokens,ref int index){var result=new Dictionary<string,object>();while(index<tokens.Length){string key=tokens[index++];if(key=="}")break;if(key=="{")throw new Exception("工坊缓存格式无法识别。");if(index>=tokens.Length)throw new Exception("工坊缓存不完整。");string value=tokens[index++];result[key.Trim('"')]=value=="{"?(object)Read(tokens,ref index):value.Trim('"');}return result;}
  static Dictionary<string,object> Section(Dictionary<string,object> data,string key){object v;return data.TryGetValue(key,out v)&&v is Dictionary<string,object>?(Dictionary<string,object>)v:new Dictionary<string,object>();}
  public static bool NeedsDownload(string vdf,ulong id,string manifest,string account,bool contentValid){var root=Section(Parse(vdf),"AppWorkshop");var installed=Section(Section(root,"WorkshopItemsInstalled"),id.ToString());var details=Section(Section(root,"WorkshopItemDetails"),id.ToString());object local,subscribed;return !contentValid||account.Length==0||!installed.TryGetValue("manifest",out local)||Convert.ToString(local)!=manifest||!details.TryGetValue("subscribedby",out subscribed)||!Regex.Matches(Convert.ToString(subscribed),@"\d+").Cast<Match>().Any(m=>m.Value==account);}
  static string ActiveAccount(){using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam\ActiveProcess")){string value=key==null?"":Convert.ToString(key.GetValue("ActiveUser"));return value=="0"?"":value;}}
  public static Dictionary<ulong,string> Query(ulong[] ids,CancellationToken cancel){var request=(HttpWebRequest)WebRequest.Create("https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/");request.Method="POST";request.ContentType="application/x-www-form-urlencoded";request.Timeout=15000;request.ReadWriteTimeout=15000;string body="itemcount="+ids.Length+string.Concat(ids.Select((id,i)=>"&publishedfileids%5B"+i+"%5D="+id));byte[] bytes=Encoding.UTF8.GetBytes(body);request.ContentLength=bytes.Length;
   using(cancel.Register(()=>request.Abort())){cancel.ThrowIfCancellationRequested();using(var output=request.GetRequestStream())output.Write(bytes,0,bytes.Length);using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){var json=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(reader.ReadToEnd());var data=(Dictionary<string,object>)json["response"];var result=new Dictionary<ulong,string>();foreach(var item in (System.Collections.IEnumerable)data["publishedfiledetails"]){var p=(Dictionary<string,object>)item;ulong id=ulong.Parse(Convert.ToString(p["publishedfileid"]));if(!ids.Contains(id)||Convert.ToString(p["result"])!="1"||Convert.ToString(p["consumer_app_id"])!="108600"||!p.ContainsKey("hcontent_file"))throw new Exception("官方工坊版本信息不可用，未自动重下。请核对工坊访问权限。");string manifest=Convert.ToString(p["hcontent_file"]);if(!Regex.IsMatch(manifest,@"^[1-9][0-9]*$"))throw new Exception("工坊版本号无效，未发起下载。");result[id]=manifest;}if(result.Count!=ids.Length)throw new Exception("工坊版本信息不完整，未发起下载。");return result;}}
  }
  static bool ContentValid(ulong id,string folder){if(!Directory.Exists(folder))return false;var addon=ViewpointAddons.All.FirstOrDefault(a=>a.Item==id);if(addon!=null){try{LauncherMaintenance.NoReparse(folder);foreach(string dir in Directory.GetDirectories(Path.Combine(folder,"mods"))){LauncherMaintenance.NoReparse(dir);foreach(string part in Directory.GetDirectories(dir).Concat(new[]{dir})){LauncherMaintenance.NoReparse(part);string info=Path.Combine(part,"mod.info"),value;if(ViewpointAddons.Metadata(info).TryGetValue("id",out value)&&value==addon.Id)return true;}}}catch{}return false;}if(id==ChinesePatch.Item){try{ChinesePatch.Validate(folder);return true;}catch{return false;}}if(id==ShootClient.Item){try{ShootClient.Validate(folder);return true;}catch{return false;}}if(id==3619862853)return File.Exists(Path.Combine(folder,"mods","ZombieBuddy","libs","ZombieBuddy.jar"))&&File.Exists(Path.Combine(folder,"mods","ZombieBuddy","libs","zbNative.dll"));return Directory.EnumerateFiles(folder,"mod.info",SearchOption.AllDirectories).Any(p=>Regex.IsMatch(File.ReadAllText(p),@"(?m)^id\s*=\s*"+(id==3809306528?"Viewpoint":"PZVoxelStudioViewpoint")+@"\s*$"));}
  public static WorkshopPlan Check(Engine engine,ulong[] ids,CancellationToken cancel){var remote=Query(ids,cancel);string cache=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(engine.Workshop)),"appworkshop_108600.acf");string vdf=File.Exists(cache)?File.ReadAllText(cache):"";string account=ActiveAccount();if(account.Length==0)throw new Exception("无法核实当前 Steam 登录账号；未自动重下或占用游戏，请登录 Steam 后重试。");var plan=new WorkshopPlan();foreach(ulong id in ids){cancel.ThrowIfCancellationRequested();string folder=Path.Combine(engine.Workshop,id.ToString());plan.Paths[id]=folder;if(NeedsDownload(vdf,id,remote[id],account,ContentValid(id,folder)))plan.Needed.Add(id);}return plan;}
 }
}
